7\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0627\u0631\u0628\u0631 \u062a\u0631\u062c\u06cc\u062d \u0645\u06cc\u200c\u062f\u0647\u062f \u067e\u0627\u0633\u062e\u200c\u0647\u0627 \u06a9\u0648\u062a\u0627\u0647 \u0628\u0627\u0634\u0646\u062f \u0648 \u0627\u0632 \u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0641\u0646\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0634\u0648\u062f. \u0627\u0648 \u062f\u0631 \u062a\u0647\u0631\u0627\u0646 \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u0632\u0628\u0627\u0646\u200c\u0647\u0627\u06cc \u0641\u0627\u0631\u0633\u06cc \u0648 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0635\u062d\u0628\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f."}, {"name": "persian_dense", "text": "\u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u0627\u06cc\u0645 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u0645. \u0646\u0645\u06cc\u200c\u062f\u0627\u0646\u0645 \u06a9\u062a\u0627\u0628\u200c\u0647\u06