u0635\u0627\u0631\u0641 \u0645\u062e\u062a\u0635\u0631 \u062c\u0648\u0627\u0628\u0627\u062a \u067e\u0633\u0646\u062f \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0644\u0627\u06c1\u0648\u0631 \u0645\u06cc\u06ba \u0631\u06c1\u062a\u0627 \u06c1\u06d2\u06d4"}, {"name": "hindi_conj", "text": "\u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\u0930 \u0930\u094d\u200d \u0915\u093e \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u0936\u093e\u0938\u094d\u0924\u094d\u0930\u0940\u092f \u0938\u0902\u0917\u0940\u0924 \u092a\u0938\u0902\u0926 \u0939\u0948\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u094d\u200d\u0937 \u0914\